export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  const out: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const chunk = text.slice(i, i + 4);
    const isLast = i + 4 === text.length;

    let pad = 0;
    if (chunk[2] === "=") {
      pad = 2;
    } else if (chunk[3] === "=") {
      pad = 1;
    }

    if (pad > 0 && !isLast) {
      throw new Error("Invalid base64: padding only allowed at the end");
    }

    let n = 0;
    for (let j = 0; j < 4; j++) {
      const c = chunk[j];
      if (j < 4 - pad) {
        const v = alphabet.indexOf(c);
        if (v < 0) {
          throw new Error(`Invalid base64 character: ${c}`);
        }
        n = (n << 6) | v;
      } else {
        if (c !== "=") {
          throw new Error("Invalid base64 padding");
        }
        n = n << 6;
      }
    }

    out.push((n >> 16) & 0xff);
    if (pad < 2) {
      out.push((n >> 8) & 0xff);
    }
    if (pad < 1) {
      out.push(n & 0xff);
    }
  }

  return out;
}

