  // appending "Z" makes lib.parseISO take its timezone branch, which is
  // computed purely in UTC. Without it, lib falls back to local-time setters.
  const normalized = `${date}T${hh}:${minute}:${second}${fraction}${offset}`;
  const ms = lib.parseISO(normalized).getTime();

  if (Number.isNaN(ms)) {
    throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(input)}`);
  }

  return ms + dayShift;
}

