  // variant digit must be 8, 9, a or b (RFC 9562 variant).
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-1([0-9a-f]{3})-([89ab][0-9a-f]{3})-([0-9a-f]{12})$/i.exec(uuid);
