    if (pad2 && !pad3) {
      throw new Error("Invalid base64 padding: '=' must be followed by '='");
    }
    if ((pad2 || pad3) && !isLastGroup) {
      throw new Error("Invalid base64 padding: '=' only allowed at end");
    }

    const v0 = decodeChar(c0);
    const v1 = decodeChar(c1);
    const v2 = pad2 ? 0 : decodeChar(c2);
    const v3 = pad3 ? 0 : decodeChar(c3);

    const n = (v0 << 18) | (v1 << 12) | (v2 << 6) | v3;

    out.push((n >> 16) & 0xff);
    if (!pad2) {
      out.push((n >> 8) & 0xff);
    }
    if (!pad3) {
      out.push(n & 0xff);
    }
  }

