    return /^fe[89ab][0-9a-f]:/i.test(addr);
  };

  if (version === undefined) return checkV4(text) || checkV6(text);
  if (version === 4) return checkV4(text);
  if (version === 6) return checkV6(text);
  return false;
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer: must be empty or start with "/": ${JSON.stringify(pointer)}`);
  }

  const tokens = pointer.slice(1).split("/");
  let current: unknown = doc;

  for (const raw of tokens) {
    // RFC 6901 order: first ~1 -> "/", then ~0 -> "~"
    const token = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Only canonical array indices are valid ("-" and leading zeros are not)
      if (!/^(0|[1-9][0-9]*)$/.test(token)) {
        return undefined;
      }
      const index = Number(token);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      // Only own properties, to avoid resolving inherited members like "constructor"
      if (!Object.prototype.hasOwnProperty.call(current, token)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[token];
    } else {
      // Primitive or null: cannot descend further
      return undefined;
    }
  }

  return current;
}

export function solve(a: string, b: string): number {
  // Keep the shorter string as `b` so the rolling rows use O(min(|a|, |b|)) memory.
  if (a.length < b.length) {
    [a, b] = [b, a];
  }

  const n = b.length;
  let prev: number[] = new Array<number>(n + 1);
  let curr: number[] = new Array<number>(n + 1);

  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= a.length; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);

    for (let j = 1; j <= n; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      let best = prev[j - 1] + cost;     // substitution or match
      const del = prev[j] + 1;           // deletion
      if (del < best) best = del;
      const ins = curr[j - 1] + 1;       // insertion
      if (ins < best) best = ins;
      curr[j] = best;
    }

    [prev, curr] = [curr, prev];
  }

  return prev[n];
}

export function solve(name: string): boolean {
  if (typeof name !== 'string' || name.length === 0) {
    return false;
  }

  // Length is measured in characters (code points), not UTF-16 code units.
  const codePointLength = (s: string): number => Array.from(s).length;

  // The whole name is at most 253 characters.
  if (codePointLength(name) > 253) {
    return false;
  }

  // A regular label: 1-63 characters of letters (incl. combining marks),
  // ASCII digits, or hyphens; must not start or end with a hyphen.
  const isLabel = (label: string): boolean => {
    const len = codePointLength(label);
    if (len < 1 || len > 63) return false;
    if (!/^[\p{L}\p{M}0-9-]+$/u.test(label)) return false;
    if (label.startsWith('-') || label.endsWith('-')) return false;
    return true;
  };

  // The TLD: a regular label of at least two characters that is either
  // all letters, or a punycode label beginning with "xn--".
  const isTld = (label: string): boolean => {
    if (!isLabel(label)) return false;
    if (codePointLength(label) < 2) return false;
    if (/^xn--/i.test(label)) return true;
    return /^[\p{L}\p{M}]+$/u.test(label);
  };

  const labels = name.split('.');

  // At least two labels. A trailing dot yields an empty last label,
  // which fails isLabel/isTld, so trailing dots are rejected.
  if (labels.length < 2) {
    return false;
  }

  const tld = labels[labels.length - 1];
  const others = labels.slice(0, -1);

  for (const label of others) {
    if (!isLabel(label)) return false;
  }

  return isTld(tld);
}

type Parsed = { major: number; minor: number; patch: number; pre: boolean };

function parseVersion(v: string): Parsed {
  const m = /^v?(\d+)\.(\d+)\.(\d+)(-[0-9A-Za-z.-]+)?(\+[0-9A-Za-z.-]+)?$/.exec(v.trim());
  if (!m) throw new Error(`Invalid semver version: ${v}`);
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    pre: m[4] !== undefined,
  };
}

function compareCore(x: Parsed, y: Parsed): number {
  if (x.major !== y.major) return x.major < y.major ? -1 : 1;
  if (x.minor !== y.minor) return x.minor < y.minor ? -1 : 1;
  if (x.patch !== y.patch) return x.patch < y.patch ? -1 : 1;
  return 0;
}

// Lower is a prerelease, higher is a release.
// Spec: highest differing core part, except the major-only / equal-core rule
// (lower minor and patch are 0) which yields `major`. The equal-core case
// uses the minor/patch rule.
function classifyPreToRelease(low: Parsed, high: Parsed): string {
  if (compareCore(low, high) === 0) {
    if (low.minor === 0 && low.patch === 0) return 'major';
    return low.minor !== 0 && low.patch === 0 ? 'minor' : 'patch';
  }

  // Only the major part changed (minor and patch remain 0)
  if (low.minor === 0 && low.patch === 0 && high.minor === 0 && high.patch === 0) {
    return 'major';
  }

  if (low.major !== high.major) return 'major';
  if (low.minor !== high.minor) return 'minor';
  return 'patch';
}

export function solve(a: string, b: string): string | null {
  // Delegate to the library for the general classification.
  const result = lib.diff(a, b);
  if (result === null) return null;

  const pa = parseVersion(a);
  const pb = parseVersion(b);

  // Determine lower and higher by semver precedence.
  const c = compareCore(pa, pb);
  const low = c !== 0 ? (c < 0 ? pa : pb) : (pa.pre ? pa : pb);
  const high = low === pa ? pb : pa;

  // The library's special-casing for prerelease -> release differs from the
  // specified rule, so that case is computed here. All other cases match the
  // library's output.
  if (low.pre && !high.pre) {
    return classifyPreToRelease(low, high);
  }

  return result;
}

export function solve(code: string): boolean {
