export function solve(uuid: string): string | null {
  // Groups: time_low, time_mid, time_hi (after the version digit 1),
  // clock_seq (variant digit 8, 9, a or b), node.
  const re =
    /^([0-9a-f]{8})-([0-9a-f]{4})-1([0-9a-f]{3})-([89ab][0-9a-f]{3})-([0-9a-f]{12})$/i;

