  if (!m) return null;

  const [, timeLow = "", timeMid = "", timeHi = "", clockSeq = "", node = ""] = m;

  // 60-bit timestamp as 15 hex digits: time_hi || time_mid || time_low
  const timestamp = (timeHi + timeMid + timeLow).toLowerCase();

  // RFC 9562 v6 field order:
  // time_high (bits 59..28) - time_mid (bits 27..12) - "6" + time_low (bits 11..0)
  // - clock_seq (unchanged) - node (unchanged)
  const v6 =
    timestamp.slice(0, 8) +
    "-" +
    timestamp.slice(8, 12) +
    "-6" +
    timestamp.slice(12, 15) +
    "-" +
    clockSeq +
    "-" +
    node;

  return v6.toLowerCase();
