  const index = new Map<string, number>();
  nodes.forEach((name, i) => {
    if (index.has(name)) {
      throw new Error(`Duplicate node: ${name}`);
    }
    index.set(name, i);
  });

  const adj: number[][] = nodes.map(() => []);
  const indegree: number[] = nodes.map(() => 0);

  for (const [a, b] of edges) {
    const ia = index.get(a);
    const ib = index.get(b);
    if (ia === undefined) {
      throw new Error(`Edge references unknown node: ${a}`);
    }
    if (ib === undefined) {
      throw new Error(`Edge references unknown node: ${b}`);
    }
    adj[ia].push(ib);
    indegree[ib]++;
  }

  // Kahn's algorithm; ties are broken by original input order.
  const queue: number[] = [];
  for (let i = 0; i < nodes.length; i++) {
    if (indegree[i] === 0) {
      queue.push(i);
    }
  }

  const result: string[] = [];
  let head = 0;
  while (head < queue.length) {
    const current = queue[head++];
    result.push(nodes[current]);
    for (const next of adj[current]) {
      indegree[next]--;
      if (indegree[next] === 0) {
        queue.push(next);
      }
    }
  }

  if (result.length !== nodes.length) {
    throw new Error("Graph contains a cycle");
  }

