const HTTP_URL_PREFIX = /^(https?):\/\/([^/?#]*)/i;
const DNS_LABEL = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
const TLD = /^(?:[a-z]{2,}|xn--[a-z0-9-]+)$/i;

function hasFqdnAuthority(authority: string): boolean {
  // Strip optional userinfo (everything up to the last '@').
  const at = authority.lastIndexOf('@');
  const hostport = at === -1 ? authority : authority.slice(at + 1);

  // Empty hosts and bracketed IPv6 literals are not domain names.
  if (hostport.length === 0 || hostport.charAt(0) === '[') {
    return false;
  }

  let host = hostport;
  const colon = hostport.indexOf(':');
  if (colon !== -1) {
    host = hostport.slice(0, colon);
    const port = hostport.slice(colon + 1);
    if (!/^\d{1,5}$/.test(port) || Number(port) > 65535) {
      return false;
    }
  }

  if (host.length === 0 || host.length > 253) {
    return false;
  }

  const labels = host.split('.');
  // At least two labels are required, so `localhost` is rejected.
  if (labels.length < 2) {
    return false;
  }
  if (!labels.every((label) => DNS_LABEL.test(label))) {
    return false;
  }

  // The top-level domain must be alphabetic (or an IDN punycode label),
  // which rejects dotted-quad IPv4 addresses such as 192.168.0.1.
  return TLD.test(labels[labels.length - 1]);
}

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    if (typeof url !== 'string') {
