    if (/\s/.test(url)) {
      return false;
    }

    const match = HTTP_URL_PREFIX.exec(url);
    if (!match) {
      return false;
    }

    if (!lib.isURL(url, LIB_OPTIONS)) {
      return false;
    }

    return hasFqdnAuthority(match[2]);
  });
}

export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error("Invalid base64 length: must be a multiple of 4");
  }

  const decodeChar = (ch: string): number => {
    const code = ch.charCodeAt(0);
    if (code >= 65 && code <= 90) return code - 65;   // A-Z -> 0-25
    if (code >= 97 && code <= 122) return code - 71;  // a-z -> 26-51
    if (code >= 48 && code <= 57) return code + 4;    // 0-9 -> 52-61
    if (code === 43) return 62;                       // +
    if (code === 47) return 63;                       // /
    throw new Error(`Invalid base64 character: ${JSON.stringify(ch)}`);
  };

  const out: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const isLastGroup = i + 4 === text.length;
    const c0 = text[i];
    const c1 = text[i + 1];
    const c2 = text[i + 2];
    const c3 = text[i + 3];

    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if ((pad2 || pad3) && !isLastGroup) {
      throw new Error("Invalid base64: padding only allowed at end");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64: malformed padding");
    }

    const v0 = decodeChar(c0);
    const v1 = decodeChar(c1);

    if (pad2) {
      // One output byte
      const n = (v0 << 18) | (v1 << 12);
      out.push((n >> 16) & 0xff);
      break;
    }

    const v2 = decodeChar(c2);

    if (pad3) {
      // Two output bytes
      const n = (v0 << 18) | (v1 << 12) | (v2 << 6);
      out.push((n >> 16) & 0xff, (n >> 8) & 0xff);
      break;
    }

    const v3 = decodeChar(c3);
    const n = (v0 << 18) | (v1 << 12) | (v2 << 6) | v3;
    out.push((n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff);
  }

  return out;
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("Invalid time value");
  }

  // Floor to whole seconds so fractional milliseconds are dropped
  // (correct for negative instants too, e.g. -1 ms -> 23:59:59).
  const seconds = Math.floor(epochMs / 1000);
  const d = new Date(seconds * 1000);

  if (Number.isNaN(d.getTime())) {
    throw new RangeError("Invalid time value");
  }

  const pad = (n: number, width: number): string => String(n).padStart(width, "0");

  const year = d.getUTCFullYear();
  const yearStr =
    year >= 0 && year <= 9999
      ? pad(year, 4)
      : (year < 0 ? "-" : "+") + pad(Math.abs(year), 6);

  const month = pad(d.getUTCMonth() + 1, 2);
  const day = pad(d.getUTCDate(), 2);
  const hours = pad(d.getUTCHours(), 2);
  const minutes = pad(d.getUTCMinutes(), 2);
  const secs = pad(d.getUTCSeconds(), 2);

  return `${yearStr}-${month}-${day}T${hours}:${minutes}:${secs}Z`;
}

