export function solve(text: string): string | null {
  const isDigit = (c: string | undefined): boolean =>
    c !== undefined && c >= "0" && c <= "9";

  const n = text.length;
  let i = 0;

  while (i < n) {
    if (!isDigit(text[i])) {
      i++;
      continue;
    }

    // i is always the start of a maximal digit run here.
    const groups: string[] = [];
    let pos = i;

    // Collect up to three dot-separated digit groups.
    while (true) {
      let k = pos;
      while (k < n && isDigit(text[k])) k++;
      groups.push(text.slice(pos, k));
      pos = k; // end of the current group

      const continues =
        groups.length < 3 &&
        text[k] === "." &&
        k + 1 < n &&
        isDigit(text[k + 1]);

      if (!continues) break;
      pos = k + 1; // start of the next group
    }

    // A run containing a number longer than 16 digits is not version-like;
    // skip the whole run and keep searching.
    if (!groups.every((g) => g.length <= 16)) {
      i = pos;
      continue;
    }

    // Leading zero in the first run (lone "0" is allowed): no later run is tried.
    if (groups.some((g) => g.length > 1 && g[0] === "0")) {
      return null;
    }

    const major = groups[0];
    const minor = groups.length > 1 ? groups[1] : "0";
    const patch = groups.length > 2 ? groups[2] : "0";
    return `${major}.${minor}.${patch}`;
  }

  return null;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");

  const isValid10 = (): boolean => {
    if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const c = s[i];
      const d = c === "X" ? 10 : c.charCodeAt(0) - 48;
      sum += (10 - i) * d;
    }
    return sum % 11 === 0;
  };

  const isValid13 = (): boolean => {
    if (!/^[0-9]{13}$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const d = s.charCodeAt(i) - 48;
      sum += (i % 2 === 0 ? 1 : 3) * d;
    }
    return sum % 10 === 0;
  };

  if (version === 10) return isValid10();
  if (version === 13) return isValid13();
  return isValid10() || isValid13();
}

const DAY_MS = 86400000;
const MIN_MS = 60000;

const PATTERN =
  /^(\d{4})(?:-(\d{2})-(\d{2})|-W(\d{2})-([1-7])|-(\d{3}))(?:T(\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?(Z|[+-]\d{2}:\d{2})?)?$/;

function invalid(input: string): never {
  throw new RangeError(`Invalid ISO 8601 date: ${JSON.stringify(input)}`);
}

function isLeap(y: number): boolean {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function daysInMonth(y: number, month: number): number {
  return [31, isLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
}

/** Number of ISO weeks (52 or 53) in ISO week-numbering year y. */
function weeksInYear(y: number): number {
  const p = (n: number): number =>
    (n + Math.floor(n / 4) - Math.floor(n / 100) + Math.floor(n / 400)) % 7;
  return p(y) === 4 || p(y - 1) === 3 ? 53 : 52;
}

/** Epoch ms of midnight UTC on the given calendar day (avoids the 0–99 year quirk of Date.UTC). */
function utcMidnight(y: number, monthIndex: number, day: number): number {
  const d = new Date(0);
  d.setUTCFullYear(y, monthIndex, day);
  return d.getTime();
}

function parseOne(input: string): number {
  if (typeof input !== "string") invalid(String(input));

  const m = PATTERN.exec(input);
  if (m === null) invalid(input);

  const year = Number(m[1]);

  // ---- Date part -------------------------------------------------------
  let dayMs: number;
  if (m[2] !== undefined) {
    // Calendar date
    const month = Number(m[2]);
    const day = Number(m[3]);
    if (month < 1 || month > 12) invalid(input);
    if (day < 1 || day > daysInMonth(year, month)) invalid(input);
    dayMs = utcMidnight(year, month - 1, day);
  } else if (m[4] !== undefined) {
    // Week date
    const week = Number(m[4]);
    const weekday = Number(m[5]); // 1 = Monday ... 7 = Sunday
    if (week < 1 || week > weeksInYear(year)) invalid(input);
    const jan4 = utcMidnight(year, 0, 4); // always in ISO week 1
    const jan4Index = (new Date(jan4).getUTCDay() + 6) % 7; // 0 = Monday
    const monday1 = jan4 - jan4Index * DAY_MS;
    dayMs = monday1 + ((week - 1) * 7 + (weekday - 1)) * DAY_MS;
  } else {
    // Ordinal date
    const ordinal = Number(m[6]);
    if (ordinal < 1 || ordinal > (isLeap(year) ? 366 : 365)) invalid(input);
    dayMs = utcMidnight(year, 0, 1) + (ordinal - 1) * DAY_MS;
  }

  // ---- Time part (optional) -------------------------------------------
  let timeMs = 0;
  let offsetMin = 0;

  if (m[7] !== undefined) {
    const hour = Number(m[7]);
    const minute = Number(m[8]);
    const second = m[9] !== undefined ? Number(m[9]) : 0;
    const frac = m[10] ?? "";
    const millis = Number((frac + "00").slice(0, 3));

    if (minute > 59) invalid(input);
    if (hour === 24) {
      // ISO 8601 permits 24:00:00 only, denoting midnight at the end of the day
      if (minute !== 0 || second !== 0 || /[1-9]/.test(frac)) invalid(input);
    } else if (hour > 23 || second > 59) {
      invalid(input);
    }

    timeMs = ((hour * 60 + minute) * 60 + second) * 1000 + millis;

    // Offset (only meaningful with a time component)
    const off = m[11];
    if (off !== undefined && off !== "Z") {
      const sign = off[0] === "+" ? 1 : -1;
      const oh = Number(off.slice(1, 3));
      const om = Number(off.slice(4, 6));
      if (oh > 23 || om > 59) invalid(input);
      offsetMin = sign * (oh * 60 + om);
    }
  }

  // No offset (or Z) means UTC.
  return dayMs + timeMs - offsetMin * MIN_MS;
}

export function solve(stamps: string[]): number[] {
  return stamps.map(parseOne).sort((a, b) => a - b);
}

export function solve(name: string, namespace: string): string {
  const uuidPattern = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
  if (typeof namespace !== "string" || !uuidPattern.test(namespace)) {
    throw new TypeError("Namespace is not a valid UUID");
  }

  // Convert the canonical namespace string into its 16 raw bytes.
  const hex = namespace.replace(/-/g, "");
  const nsBytes: number[] = [];
  for (let i = 0; i < 32; i += 2) {
    nsBytes.push(parseInt(hex.substring(i, i + 2), 16));
  }

  const result = lib.v3(name, nsBytes);
  return String(result).toLowerCase();
}

