export function solve(text: string): string {
    // Manually encode the string as UTF-8, replacing lone surrogates with U+FFFD
    // (matching the behavior of TextEncoder).
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);

        // Combine surrogate pairs into a single code point.
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const next = text.charCodeAt(i + 1);
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            }
        }

        // Any remaining lone surrogate becomes U+FFFD.
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest: Uint8Array = lib.sha1(Uint8Array.from(bytes));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        hex += digest[i].toString(16).padStart(2, "0");
    }
    return hex;
}

export function solve(card: string): boolean {
  const digits = card.replace(/[ -]/g, "");
  if (!/^\d+$/.test(digits)) return false;

  // Numeric value of the first n digits, or NaN if the number is too short.
  const prefix = (d: string, n: number): number =>
    d.length >= n ? Number(d.slice(0, n)) : NaN;

  const range = (lo: number, hi: number): number[] => {
    const out: number[] = [];
    for (let i = lo; i <= hi; i++) out.push(i);
    return out;
  };

  const issuers: { match: (d: string) => boolean; lengths: number[] }[] = [
    // Visa
    {
      match: (d) => d[0] === "4",
      lengths: [13, 16, 19],
    },
    // Mastercard
    {
      match: (d) => {
        const p2 = prefix(d, 2);
        const p4 = prefix(d, 4);
        return (p2 >= 51 && p2 <= 55) || (p4 >= 2221 && p4 <= 2720);
      },
      lengths: [16],
    },
    // American Express
    {
      match: (d) => {
        const p2 = prefix(d, 2);
        return p2 === 34 || p2 === 37;
      },
      lengths: [15],
    },
    // Discover
    {
      match: (d) => {
        const p2 = prefix(d, 2);
        const p3 = prefix(d, 3);
        const p4 = prefix(d, 4);
        const p6 = prefix(d, 6);
        return (
          p4 === 6011 ||
          (p6 >= 622126 && p6 <= 622925) ||
          (p3 >= 644 && p3 <= 649) ||
          p2 === 65
        );
      },
      lengths: [16, 19],
    },
    // Diners Club
    {
      match: (d) => {
        const p2 = prefix(d, 2);
        const p3 = prefix(d, 3);
        return (p3 >= 300 && p3 <= 305) || p2 === 36 || p2 === 38;
      },
      lengths: range(14, 19),
    },
    // JCB
    {
      match: (d) => {
        const p4 = prefix(d, 4);
        return p4 >= 3528 && p4 <= 3589;
      },
      lengths: range(16, 19),
    },
    // UnionPay
    {
      match: (d) => prefix(d, 2) === 62,
      lengths: range(16, 19),
    },
  ];

  const matched = issuers.some(
    (issuer) => issuer.match(digits) && issuer.lengths.includes(digits.length)
  );
  if (!matched) return false;

  // Luhn check
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48;
    if (double) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    double = !double;
  }
