  // Luhn check over the full digit string, scanning from the right.
  // The rightmost digit (the check digit) is not doubled; every second digit after it is.
  let sum = 0;
  let double = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48;
    if (double) {
      d *= 2;
      if (d > 9) {
        d -= 9;
      }
    }
    sum += d;
    double = !double;
  }

  return sum % 10 === 0;
}

