  // 'major' applies only when the major part differs (or the cores are equal).
  // Correct that case here.
  const x = parseVersion(a);
  const y = parseVersion(b);

  // Only the prerelease -> release case with equal majors can be affected.
  if (x.pre === y.pre || x.major !== y.major) {
    return result;
  }

  const pre = x.pre ? x : y; // lower version (prerelease)
  const rel = x.pre ? y : x; // higher version (release)

  if (pre.minor !== 0 || pre.patch !== 0) {
    return result;
  }

