  if (rel.minor === 0 && rel.patch === 0) {
    return 'major';
  }

  // Highest differing part below the major
  return rel.minor !== 0 ? 'minor' : 'patch';
}

export function solve(a: string, b: string): number {
  // Keep the shorter string as the row dimension to use O(min(|a|, |b|)) memory.
  let s = a;
  let t = b;
  if (s.length < t.length) {
    const tmp = s;
    s = t;
    t = tmp;
  }

  const n = t.length;
  let prev = new Array<number>(n + 1);
  let curr = new Array<number>(n + 1);

  for (let j = 0; j <= n; j++) {
    prev[j] = j;
  }

  for (let i = 1; i <= s.length; i++) {
    curr[0] = i;
    const sc = s.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) {
      const cost = sc === t.charCodeAt(j - 1) ? 0 : 1;
      let best = prev[j - 1] + cost; // substitution or match
      const del = prev[j] + 1;       // deletion
      if (del < best) best = del;
      const ins = curr[j - 1] + 1;   // insertion
      if (ins < best) best = ins;
      curr[j] = best;
    }
    const swap = prev;
    prev = curr;
    curr = swap;
  }

  return prev[n];
}

