      value = LETTER_VALUES[ch.charCodeAt(0) - 65];
    }
    sum += value * Math.pow(2, i);
  }

  const checkDigit = (sum % 11) % 10;
  return checkDigit === s.charCodeAt(10) - 48;
}

export function solve(id: string): boolean {
  // Remove all slashes and backslashes
  const s = id.replace(/[\/\\]/g, "");

  // Must be exactly 11 ASCII digits, first digit not 0
  if (!/^[0-9]{11}$/.test(s)) return false;
  if (s[0] === "0") return false;

  const digits: number[] = [];
  for (let i = 0; i < 11; i++) {
    digits.push(s.charCodeAt(i) - 48);
  }

  // Track occurrences and positions of each digit among the first 10
  const counts: number[] = Array.from({ length: 10 }, () => 0);
  const positions: number[][] = Array.from({ length: 10 }, () => []);
  for (let i = 0; i < 10; i++) {
    counts[digits[i]]++;
    positions[digits[i]].push(i);
  }

  let repeatedDigits = 0;
  for (let d = 0; d < 10; d++) {
    const c = counts[d];
    if (c > 3) return false;
    if (c === 2) {
      repeatedDigits++;
    } else if (c === 3) {
      repeatedDigits++;
      const p = positions[d];
      // Three occurrences must not all be directly next to each other
      if (p[2] - p[0] === 2) return false;
    }
  }

  // Exactly one digit may occur more than once
  if (repeatedDigits !== 1) return false;

  // ISO 7064 MOD 11,10 check digit over the first 10 digits
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (digits[i] + product) % 10;
    if (sum === 0) sum = 10;
    product = (sum * 2) % 11;
  }
  const check = (11 - product) % 10;

  return check === digits[10];
}

export function solve(uuid: string): string | null {
  if (typeof uuid !== "string") return null;
  if (!/^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/.test(uuid)) {
    return null;
  }

  const h = uuid.replace(/-/g, "").toLowerCase(); // 32 hex digits

  // Variant digit is the first nibble of the clock_seq_hi_and_reserved byte.
  const variant = h[16];
  if (!"89ab".includes(variant)) return null;

  // UUIDv1 fields: time_low(0..8) time_mid(8..12) version+time_hi(12..16)
  //                clock_seq(16..20) node(20..32)
  const timeLow = h.slice(0, 8);
  const timeMid = h.slice(8, 12);
  const timeHi = h.slice(13, 16); // 12-bit time_hi, version nibble skipped
  const clockSeq = h.slice(16, 20);
  const node = h.slice(20, 32);

  // 60-bit timestamp as 15 hex digits: time_hi | time_mid | time_low
  const ts = timeHi + timeMid + timeLow;

  // UUIDv6 fields: time_high(32) time_mid(16) version+time_low(12)
  //                clock_seq(16) node(48)
  const timeHigh = ts.slice(0, 8);
  const v6Mid = ts.slice(8, 12);
  const v6Low = ts.slice(12, 15);

  return `${timeHigh}-${v6Mid}-6${v6Low}-${clockSeq}-${node}`;
}

export function solve(text: string): string | null {
  // Maximal runs of digits, optionally joined by single dots.
  const runs = text.match(/\d+(?:\.\d+)*/g) ?? [];

  for (const run of runs) {
    // Only the first three numbers matter; anything after is ignored.
    const parts = run.split(".").slice(0, 3);

    // A run with a number longer than 16 digits is not version-like; try the next run.
    if (parts.some((p) => p.length > 16)) continue;

    // First version-like run decides the result: a leading zero means null.
    if (parts.some((p) => p.length > 1 && p[0] === "0")) return null;

    const [major, minor = "0", patch = "0"] = parts;
    return `${major}.${minor}.${patch}`;
  }

  return null;
}
